import type { SliderProps } from "./slider.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Slider";

// Generate child element class names for the component, should match available style slots
export const SliderClasses = {
  root: "exp-textura_slider",
  sliderRoot: "exp-textura_slider_root",
  track: "exp-textura_slider_track",
  thumb: "exp-textura_slider_thumb",
  range: "exp-textura_slider_range",
  labelContainer: "exp-textura_slider_label_container",
  labelMin: "exp-textura_slider_label_min",
  labelMax: "exp-textura_slider_label_max",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: SliderProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SliderProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    width: "100%",
    [`& .${SliderClasses.sliderRoot}`]: {
      alignItems: "center",
      userSelect: "none",
      touchAction: "none",
      width: "100%",
      display: "flex",
      position: "relative",
      borderRadius: theme.toRem(theme.border.radius.sm),

      [`&[data-disabled]`]: {
        ...styleSlots?.disabled,
      },
      ...styleSlots?.sliderRoot,
    },

    [`& .${SliderClasses.labelContainer}`]: {
      width: "100%",
      height: "1rem",
      display: "flex",
      marginBottom: theme.toRem(theme.spacing[8]),
      justifyContent: "space-between",
      ...theme.typography.body.md,
      ...styleSlots?.labelContainer,
    },

    [`& .${SliderClasses.labelMin}`]: {
      color: theme.color.content.default,
      ...styleSlots?.labelMin,
    },

    [`& .${SliderClasses.labelMax}`]: {
      color: theme.color.content.default,
      ...styleSlots?.labelMax,
    },

    [`& .${SliderClasses.track}`]: {
      backgroundColor: theme.inputSlider.track.color.enabled,
      borderColor: theme.inputSlider.track.color.enabled,
      borderWidth: theme.toRem(theme.inputSlider.track.border.enabled),
      borderStyle: "solid",
      position: "relative",
      flexGrow: 1,
      borderRadius: theme.toRem(theme.border.radius.lg),
      height: theme.toRem(4),

      [`.${SliderClasses.sliderRoot}:hover:not([data-disabled]) &`]: {
        backgroundColor: theme.inputSlider.track.color.hover,
        borderWidth: theme.toRem(theme.inputSlider.track.border.hover),
      },

      [`.${SliderClasses.sliderRoot}:active:not([data-disabled]) &`]: {
        backgroundColor: theme.inputSlider.track.color.pressed,
        borderWidth: theme.toRem(theme.inputSlider.track.border.pressed),
      },

      "&[data-disabled]": {
        backgroundColor: theme.inputSlider.track.color.disabled,
        borderWidth: theme.toRem(theme.inputSlider.track.border.disabled),
        ...styleSlots?.trackDisabled,
      },
      ...styleSlots?.track,
    },

    [`& .${SliderClasses.range}`]: {
      backgroundColor: theme.inputSlider.filled.color.enabled,
      borderColor: theme.inputSlider.filled.color.enabled,
      borderWidth: theme.toRem(theme.inputSlider.filled.border.enabled),
      position: "absolute",
      borderRadius: theme.toRem(theme.border.radius.lg),
      height: "100%",

      [`.${SliderClasses.sliderRoot}:hover:not([data-disabled]) &`]: {
        backgroundColor: theme.inputSlider.filled.color.hover,
        borderWidth: theme.toRem(theme.inputSlider.filled.border.hover),
      },

      [`.${SliderClasses.sliderRoot}:active:not([data-disabled]) &`]: {
        backgroundColor: theme.inputSlider.filled.color.pressed,
        borderWidth: theme.toRem(theme.inputSlider.filled.border.pressed),
      },

      "&[data-disabled]": {
        backgroundColor: theme.inputSlider.filled.color.disabled,
        borderWidth: theme.toRem(theme.inputSlider.filled.border.disabled),
        ...styleSlots?.rangeDisabled,
      },
      ...styleSlots?.range,
    },

    [`& .${SliderClasses.thumb}`]: {
      display: "block",
      cursor: "pointer",
      width: theme.toRem(16),
      height: theme.toRem(16),
      boxSizing: "unset",
      backgroundColor: theme.inputSlider.handle.color.enabled,
      borderRadius: theme.toRem(theme.border.radius.lg),
      boxShadow: "none",
      borderStyle: "solid",
      borderColor: theme.inputSlider.handle.color.enabled,
      borderWidth: theme.toRem(theme.inputSlider.handle.border.enabled),

      "&:hover:not(:active):not([data-disabled])": {
        backgroundColor: theme.inputSlider.handle.color.hover,
        borderColor: theme.inputSlider.handle.color.hover,
        borderWidth: theme.toRem(theme.inputSlider.handle.border.hover),
        boxShadow: theme.dropShadow.sm,
        ...styleSlots?.thumbHover,
      },

      "&:active:not([data-disabled])": {
        backgroundColor: theme.inputSlider.handle.color.pressed,
        borderColor: theme.inputSlider.handle.color.pressed,
        borderWidth: theme.toRem(theme.inputSlider.handle.border.pressed),
        boxShadow: theme.dropShadow.lg,
        ...styleSlots?.thumbPressed,
      },

      "&:focus-visible": {
        outline: "none",
        ...styleSlots?.thumbFocus,
      },

      [`&[data-disabled]`]: {
        cursor: "not-allowed",
        backgroundColor: theme.inputSlider.handle.color.disabled,
        borderWidth: theme.toRem(theme.inputSlider.handle.border.disabled),
        boxShadow: "none",
        borderColor: theme.inputSlider.handle.color.disabled,
        ...styleSlots?.thumbDisabled,
      },
      ...styleSlots?.thumb,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSlider = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SliderProps>((props) => generateStyles(props));
